1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strings"
12	)
13	
14	// Reason constants for clusters that cannot enter a release plan.
15	const (
16		ReasonDisabled          = "集群已停用"
17		ReasonExcludeMatched    = "命中排除条件"
18		ReasonIncludeNotMatched = "未命中包含条件"
19	)
20	
21	// LabelCondition is a set of exact key-value matches; all must match.
22	type LabelCondition map[string]string
23	
24	// Cluster is a candidate target for a release.
25	type Cluster struct {
26		ID       string
27		Disabled bool
28		Tags     map[string]string
29	}
30	
31	// ReleasePlanInput describes an application release to plan offline.
32	type ReleasePlanInput struct {
33		App       string
34		Revision  string
35		Image     string
36		BatchSize int
37		Clusters  []Cluster
38		Include   []LabelCondition
39		Exclude   []LabelCondition
40		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
41		// fault domain; each batch then contains at most one cluster per domain.
42		SpreadBy string
43	}
44	
45	// AppInfo identifies the application being released.
46	type AppInfo struct {
47		Name     string `json:"name"`
48		Revision string `json:"revision"`
49		Image    string `json:"image"`
50	}
51	
52	// Batch is a sequentially numbered group of cluster IDs.
53	type Batch struct {
54		Index    int      `json:"index"`
55		Clusters []string `json:"clusters"`
56	}
57	
58	// ExcludedCluster explains why a cluster is not in the plan.
59	type ExcludedCluster struct {
60		ID     string `json:"id"`
61		Reason string `json:"reason"`
62	}
63	
64	// ReleasePlan is the deterministic offline release plan.
65	type ReleasePlan struct {
66		App      AppInfo           `json:"app"`
67		Batches  []Batch           `json:"batches"`
68		Excluded []ExcludedCluster `json:"excluded"`
69	}
70	
71	// ParseReleaseInput reads a release plan document and validates its fields.
72	// Every string in the document — member names and values, in known fields
73	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
74	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
75	// decoded string can be silently rewritten to "�" and compared. Every JSON
76	// object in the document — including unknown fields and their nested
77	// objects — must then have distinct member names; a name appearing twice
78	// (even with the same value, or via equivalent Unicode escapes) is rejected
79	// before any business validation runs. The document's structural nesting
80	// is capped at maxJSONNestingDepth levels in every field, known or not; a
81	// document that opens a 10001st level is rejected with
82	// errJSONDepthExceeded before any business validation or planning runs.
83	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
84		if err := checkStrictText(data); err != nil {
85			return ReleasePlanInput{}, err
86		}
87		if err := checkDuplicateMembers(data); err != nil {
88			return ReleasePlanInput{}, err
89		}
90		dec := json.NewDecoder(bytes.NewReader(data))
91		dec.UseNumber()
92		var doc map[string]any
93		if err := dec.Decode(&doc); err != nil {
94			if isJSONDepthError(err) {
95				return ReleasePlanInput{}, errJSONDepthExceeded
96			}
97			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
98		}
99		if dec.More() {
100			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
101		}
102		return buildReleaseInput(doc)
103	}
104	
105	// duplicateMemberError reports a JSON object whose member name appears more
106	// than once. Path is a JSONPath-style location that points at the object
107	// owning the duplicate (the duplicate member name itself is reported
108	// separately in field): "$" for the document root, "$.clusters[1]" for a
109	// cluster, "$.clusters[0].tags" for a tag object,
110	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
111	// objects nested inside unknown fields. A member name that is not a plain
112	// identifier is wrapped in brackets around a JSON string, so that characters
113	// in the name can never be read as hierarchy or an array index: a top-level
114	// member "meta.info" is at $["meta.info"] (distinct from the nested object
115	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
116	// that are empty or contain quotes, backslashes or control characters are
117	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
118	type duplicateMemberError struct {
119		field string
120		path  string
121	}
122	
123	func (e *duplicateMemberError) Error() string {
124		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
125	}
126	
127	// checkDuplicateMembers walks every JSON object in data and rejects objects
128	// with duplicate member names. Names are compared after JSON decoding, so
129	// "env" and "env" are the same name while "env" and "ENV", or
130	// " env" and "env", are different. The first duplicate encountered in file
131	// order is reported: the walk is depth-first in document order, so the
132	// second occurrence that appears earliest wins, regardless of value type.
133	//
134	// The check is a policy over the shared structural walk (jsonwalk.go): the
135	// walker recognizes the nesting, decodes the member names and tracks each
136	// object's location; this check only keeps the seen-name set of each object.
137	// A document the walk cannot fully vouch for — an unrecognized structure,
138	// trailing content, or a loosely scanned number only the decoder judges —
139	// is handed to the encoding/json walk, which reports the established format
140	// error (and any duplicate preceding the malformation) with the existing
141	// wording.
142	func checkDuplicateMembers(data []byte) error {
143		dup, recognized := scanDuplicateMembers(data)
144		// The nesting limit is a verdict by itself: it holds whether or not the
145		// document is otherwise well-formed and needs no json.Valid confirmation,
146		// so a too-deep document stops here instead of being scanned twice.
147		if errors.Is(dup, errJSONDepthExceeded) {
148			return dup
149		}
150		// json.Valid confirms the whole document — including the numbers the
151		// walk skipped loosely and any trailing content — is one well-formed
152		// JSON value, so a completed walk's verdict can be trusted directly.
153		// Legal numbers beyond float64 range (e.g. 1e400) are valid JSON and
154		// pass; whether a number is acceptable for a given field is decided
155		// later by business validation.
156		if recognized && json.Valid(data) {
157			return dup
158		}
159		return checkJSONFormatAndDuplicates(data)
160	}
161	
162	// scanDuplicateMembers runs the duplicate-member policy over the shared
163	// structural walk. It reports the first duplicate in file order — the walk
164	// is depth-first in document order, so the second occurrence that appears
165	// earliest wins — and whether the walk recognized the document's structure
166	// (no errUndecided and no text problem, both of which leave the verdict to
167	// the decoder walk). recognized does not by itself mean the document is
168	// well-formed JSON: the caller confirms that with json.Valid.
169	func scanDuplicateMembers(data []byte) (dup error, recognized bool) {
170		// Each entered object's frame id is unique, so the seen-name sets are
171		// keyed by the owning object's id; the walk needs no enter/exit events
172		// for them.
173		seen := make(map[uint64]map[string]struct{})
174		var w *jsonWalker
175		w = &jsonWalker{data: data, onMember: func(ownerID uint64, name string) error {
176			set := seen[ownerID]
177			if set == nil {
178				set = make(map[string]struct{})
179				seen[ownerID] = set
180			}
181			if _, ok := set[name]; ok {
182				dup = &duplicateMemberError{field: name, path: w.framePathByID(ownerID)}
183				return dup
184			}
185			set[name] = struct{}{}
186			return nil
187		}}
188		if err := w.walk(); err != nil && dup == nil {
189			if errors.Is(err, errJSONDepthExceeded) {
190				return err, true
191			}
192			return nil, false
193		}
194		return dup, true
195	}
196	
197	// checkJSONFormatAndDuplicates is the encoding/json walk that documents the
198	// raw structural walk cannot recognize are handed to. It reports the JSON
199	// format error with the established wording — and a duplicate member when
200	// its second occurrence precedes the malformation — exactly as the duplicate
201	// check always has for such documents. The Token API enforces no nesting
202	// limit of its own, so the walk carries the same maxJSONNestingDepth
203	// counter: a malformed document that is also too deep (e.g. one with no
204	// closing brackets at all) is refused with errJSONDepthExceeded instead of
205	// recursing down the reader's call stack and reporting "unclosed" later.
206	func checkJSONFormatAndDuplicates(data []byte) error {
207		dec := json.NewDecoder(bytes.NewReader(data))
208		// Numbers are only walked past, never interpreted: UseNumber keeps legal
209		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
210		// unmarshal-overflow error here. Whether a number is acceptable for a given
211		// field is decided later by business validation.
212		dec.UseNumber()
213		depth := 0
214		if err := walkJSONValue(dec, "$", &depth); err != nil {
215			return err
216		}
217		if _, err := dec.Token(); err != io.EOF {
218			if err == nil {
219				return errors.New("JSON 格式错误: 文档包含多余内容")
220			}
221			if isJSONDepthError(err) {
222				return errJSONDepthExceeded
223			}
224			return fmt.Errorf("JSON 格式错误: %w", err)
225		}
226		return nil
227	}
228	
229	// enterContainer enforces the shared nesting limit on the Token walk: the
230	// root container is level 1 and each entered object or array adds one,
231	// exactly as in the raw walker. It returns errJSONDepthExceeded at the
232	// 10001st level.
233	func enterContainer(depth *int) error {
234		*depth++
235		if *depth > maxJSONNestingDepth {
236			return errJSONDepthExceeded
237		}
238		return nil
239	}
240	
241	// leaveContainer marks one container closed.
242	func leaveContainer(depth *int) {
243		*depth--
244	}
245	
246	// walkJSONValue reads one complete JSON value whose first token has not been
247	// consumed yet. Together with walkJSONObject and walkJSONArray it is the
248	// decoding half of checkJSONFormatAndDuplicates: it only runs for documents
249	// the shared structural walk could not recognize, to report the format error
250	// (or an earlier duplicate) with the established wording.
251	func walkJSONValue(dec *json.Decoder, path string, depth *int) error {
252		tok, err := dec.Token()
253		if err != nil {
254			if err == io.EOF {
255				return errors.New("JSON 格式错误: 文档为空")
256			}
257			if isJSONDepthError(err) {
258				return errJSONDepthExceeded
259			}
260			return fmt.Errorf("JSON 格式错误: %w", err)
261		}
262		return walkJSONValueToken(dec, path, tok, depth)
263	}
264	
265	// walkJSONValueToken reads the remainder of a value given its first token.
266	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token, depth *int) error {
267		if d, ok := tok.(json.Delim); ok {
268			if err := enterContainer(depth); err != nil {
269				return err
270			}
271			switch d {
272			case '{':
273				return walkJSONObject(dec, path, depth)
274			case '[':
275				return walkJSONArray(dec, path, depth)
276			default:
277				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
278			}
279		}
280		return nil // scalar value (string, number, bool, null)
281	}
282	
283	func walkJSONObject(dec *json.Decoder, path string, depth *int) error {
284		defer leaveContainer(depth)
285		seen := make(map[string]struct{})
286		for {
287			tok, err := dec.Token()
288			if err != nil {
289				if err == io.EOF {
290					return errors.New("JSON 格式错误: 对象未闭合")
291				}
292				if isJSONDepthError(err) {
293					return errJSONDepthExceeded
294				}
295				return fmt.Errorf("JSON 格式错误: %w", err)
296			}
297			if d, ok := tok.(json.Delim); ok {
298				if d == '}' {
299					return nil
300				}
301				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
302			}
303			key, ok := tok.(string)
304			if !ok {
305				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
306			}
307			if _, dup := seen[key]; dup {
308				return &duplicateMemberError{field: key, path: path}
309			}
310			seen[key] = struct{}{}
311			vtok, err := dec.Token()
312			if err != nil {
313				if err == io.EOF {
314					return errors.New("JSON 格式错误: 缺少成员值")
315				}
316				if isJSONDepthError(err) {
317					return errJSONDepthExceeded
318				}
319				return fmt.Errorf("JSON 格式错误: %w", err)
320			}
321			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok, depth); err != nil {
322				return err
323			}
324		}
325	}
326	
327	func walkJSONArray(dec *json.Decoder, path string, depth *int) error {
328		defer leaveContainer(depth)
329		for i := 0; ; i++ {
330			tok, err := dec.Token()
331			if err != nil {
332				if err == io.EOF {
333					return errors.New("JSON 格式错误: 数组未闭合")
334				}
335				if isJSONDepthError(err) {
336					return errJSONDepthExceeded
337				}
338				return fmt.Errorf("JSON 格式错误: %w", err)
339			}
340			if d, ok := tok.(json.Delim); ok && d == ']' {
341				return nil
342			}
343			if err := walkJSONValueToken(dec, joinIndexPath(path, i), tok, depth); err != nil {
344				return err
345			}
346		}
347	}
348	
349	// isJSONDepthError reports whether err is encoding/json's own
350	// nesting-limit failure (Decode/Valid enforce it even though the Token
351	// API does not). The message is matched rather than a typed error,
352	// because the scanner's "exceeded max depth" SyntaxError is not exported
353	// as one.
354	func isJSONDepthError(err error) bool {
355		return err != nil && strings.Contains(err.Error(), "exceeded max depth")
356	}
357	
358	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
359		app, err := requiredString(doc, "app")
360		if err != nil {
361			return ReleasePlanInput{}, err
362		}
363		revision, err := requiredString(doc, "revision")
364		if err != nil {
365			return ReleasePlanInput{}, err
366		}
367		image, err := requiredString(doc, "image")
368		if err != nil {
369			return ReleasePlanInput{}, err
370		}
371		batchSize, err := positiveInt(doc, "batchSize")
372		if err != nil {
373			return ReleasePlanInput{}, err
374		}
375		spreadBy, err := optionalSpreadBy(doc)
376		if err != nil {
377			return ReleasePlanInput{}, err
378		}
379		clusters, err := parseClusters(doc["clusters"])
380		if err != nil {
381			return ReleasePlanInput{}, err
382		}
383		include, err := parseConditions(doc, "include")
384		if err != nil {
385			return ReleasePlanInput{}, err
386		}
387		exclude, err := parseConditions(doc, "exclude")
388		if err != nil {
389			return ReleasePlanInput{}, err
390		}
391	
392		return ReleasePlanInput{
393			App:       app,
394			Revision:  revision,
395			Image:     image,
396			BatchSize: batchSize,
397			Clusters:  clusters,
398			Include:   include,
399			Exclude:   exclude,
400			SpreadBy:  spreadBy,
401		}, nil
402	}
403	
404	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
405	// string disables fault-domain spreading; a non-string value or a string of
406	// only whitespace is rejected. The tag key is used exactly as written.
407	func optionalSpreadBy(doc map[string]any) (string, error) {
408		v, ok := doc["spreadBy"]
409		if !ok {
410			return "", nil
411		}
412		s, ok := v.(string)
413		if !ok {
414			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
415		}
416		if err := checkSpreadBy(s); err != nil {
417			return "", err
418		}
419		return s, nil
420	}
421	
422	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
423	// tag key: a string of only whitespace can never match a valid tag key.
424	func checkSpreadBy(s string) error {
425		if s != "" && strings.TrimSpace(s) == "" {
426			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
427		}
428		return nil
429	}
430	
431	// ValidateReleaseInput checks that a release configuration is well-formed.
432	// Every string is first required to be legal UTF-8 — app, revision, image,
433	// spreadBy, every candidate's ID and tag keys/values (disabled and
434	// filtered-out candidates included), and every include/exclude condition's
435	// keys and values — because invalid bytes would later be rewritten to "�"
436	// while the plan is written as JSON and could merge two distinct identities
437	// or take part in label matching as an ordinary value. That text check runs
438	// before any business rule, in a fixed order (field order, then candidate
439	// and condition positions from zero, then keys in ascending order), so the
440	// one problem it reports never depends on map iteration. Business
441	// validation then runs as before: app/revision/image are non-empty,
442	// batchSize is a positive integer, spreadBy is empty or a usable tag key
443	// (not whitespace-only), cluster IDs are unique across every candidate
444	// (including disabled and filtered-out clusters), and tag/condition keys
445	// are non-empty. Errors name the field and the position in its list; within
446	// a cluster the ID is checked before its tags, and tag keys are examined in
447	// ascending order so repeated calls report the same error. The input is
448	// never mutated. MakeReleasePlan calls this automatically; library callers
449	// may use it to validate without planning.
450	func ValidateReleaseInput(in ReleasePlanInput) error {
451		if err := validateStrictText(in); err != nil {
452			return err
453		}
454		if strings.TrimSpace(in.App) == "" {
455			return errors.New(`字段 "app" 不能为空或只含空白`)
456		}
457		if strings.TrimSpace(in.Revision) == "" {
458			return errors.New(`字段 "revision" 不能为空或只含空白`)
459		}
460		if strings.TrimSpace(in.Image) == "" {
461			return errors.New(`字段 "image" 不能为空或只含空白`)
462		}
463		if in.BatchSize <= 0 {
464			return errors.New(`字段 "batchSize" 必须是正整数`)
465		}
466		if err := checkSpreadBy(in.SpreadBy); err != nil {
467			return err
468		}
469		ids := newClusterIDSet(len(in.Clusters))
470		for i, c := range in.Clusters {
471			if err := ids.check(i, c.ID); err != nil {
472				return err
473			}
474			if err := validateTagKeys(i, c.Tags); err != nil {
475				return err
476			}
477		}
478		if err := validateConditionKeys("include", in.Include); err != nil {
479			return err
480		}
481		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
482			return err
483		}
484		return nil
485	}
486	
487	// validateTagKeys applies the shared label-key rule to one cluster's tags,
488	// reporting the cluster's position in the candidate list.
489	func validateTagKeys(clusterIndex int, tags map[string]string) error {
490		if hasEmptyLabelKey(tags) {
491			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
492		}
493		return nil
494	}
495	
496	// validateConditionKeys applies the shared condition rules to every condition
497	// in original order, so the first invalid condition is reported.
498	func validateConditionKeys(field string, conds []LabelCondition) error {
499		for i, cond := range conds {
500			if err := validateCondition(field, i, cond); err != nil {
501				return err
502			}
503		}
504		return nil
505	}
506	
507	func requiredString(doc map[string]any, field string) (string, error) {
508		v, ok := doc[field]
509		if !ok {
510			return "", fmt.Errorf("缺少必需字段 %q", field)
511		}
512		s, ok := v.(string)
513		if !ok {
514			return "", fmt.Errorf("字段 %q 必须是字符串", field)
515		}
516		if strings.TrimSpace(s) == "" {
517			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
518		}
519		return s, nil
520	}
521	
522	// positiveInt reads a required field as a positive integer. The literal must
523	// be an integral JSON number whose value is representable in full by the Go
524	// int of the running environment: a value beyond math.MaxInt is rejected here
525	// rather than narrowed by an int() conversion, which on a 32-bit environment
526	// could turn 4294967297 into 1 (or a larger value into zero or a negative
527	// number). No truncation, rounding, default substitution or clamping to the
528	// maximum ever happens — such a value is a configuration error regardless of
529	// what int it would collapse into.
530	func positiveInt(doc map[string]any, field string) (int, error) {
531		v, ok := doc[field]
532		if !ok {
533			return 0, fmt.Errorf("缺少必需字段 %q", field)
534		}
535		n, ok := v.(json.Number)
536		if !ok {
537			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
538		}
539		i, err := n.Int64()
540		if err != nil || i <= 0 || i > math.MaxInt {
541			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
542		}
543		return int(i), nil
544	}
545	
546	func parseClusters(v any) ([]Cluster, error) {
547		if v == nil {
548			return nil, errors.New("缺少必需字段 \"clusters\"")
549		}
550		raw, ok := v.([]any)
551		if !ok {
552			return nil, errors.New("字段 \"clusters\" 必须是数组")
553		}
554		clusters := make([]Cluster, 0, len(raw))
555		ids := newClusterIDSet(len(raw))
556		for i, item := range raw {
557			obj, ok := item.(map[string]any)
558			if !ok {
559				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
560			}
561			id, err := clusterIDFromJSON(obj, i, ids)
562			if err != nil {
563				return nil, err
564			}
565	
566			disabled := false
567			if dv, present := obj["disabled"]; present {
568				b, ok := dv.(bool)
569				if !ok {
570					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
571				}
572				disabled = b
573			}
574	
575			tags := map[string]string{}
576			if tv, present := obj["tags"]; present {
577				tm, ok := tv.(map[string]any)
578				if !ok {
579					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
580				}
581				tags, err = labelsFromJSON(tm,
582					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
583					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
584				)
585				if err != nil {
586					return nil, err
587				}
588			}
589	
590			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
591		}
592		return clusters, nil
593	}
594	
595	// clusterIDFromJSON reads the "id" member of one candidate object and applies
596	// the shared cluster-identity rule. A missing member or a non-string value is
597	// a JSON decoding problem with its own reason; an empty or duplicate ID is
598	// reported by the shared rule exactly as for a directly constructed config.
599	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
600		v, ok := obj["id"]
601		if !ok {
602			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
603		}
604		id, ok := v.(string)
605		if !ok {
606			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
607		}
608		if err := ids.check(index, id); err != nil {
609			return "", err
610		}
611		return id, nil
612	}
613	
614	// parseConditions reads the optional include/exclude field from the decoded
615	// document. An absent field means "no conditions" (the same as an explicit
616	// empty array); a field that is present must be an array of condition
617	// objects. An explicit JSON null is a field type error — it must not be read
618	// as "no conditions", which would silently drop the filter the author wrote.
619	func parseConditions(doc map[string]any, field string) ([]LabelCondition, error) {
620		v, ok := doc[field]
621		if !ok {
622			return []LabelCondition{}, nil
623		}
624		raw, ok := v.([]any)
625		if !ok {
626			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
627		}
628		conds := make([]LabelCondition, 0, len(raw))
629		for i, item := range raw {
630			obj, ok := item.(map[string]any)
631			if !ok {
632				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
633			}
634			cond, err := labelsFromJSON(obj,
635				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
636				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
637			)
638			if err != nil {
639				return nil, err
640			}
641			if err := validateCondition(field, i, cond); err != nil {
642				return nil, err
643			}
644			conds = append(conds, cond)
645		}
646		return conds, nil
647	}
648	
649	// MakeReleasePlan selects available clusters, orders them by ID, and splits
650	// them into batches. When SpreadBy names a tag, each batch holds at most one
651	// cluster per value of that tag (its fault domain) and every selected cluster
652	// must carry the tag. It validates the input first and never mutates it.
653	//
654	// When every candidate is filtered out, the returned error lists each
655	// candidate's rejection reason on its own line, ascending by the original
656	// ID. An ID containing a double quote, backslash, control character or
657	// U+2028/U+2029 is displayed as a quoted JSON string with those characters
658	// escaped (see rejectreport.go), so one candidate always occupies exactly
659	// one line and the original ID can be recovered from the display; this is
660	// only a display spelling — the ID itself is never altered or re-compared.
661	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
662		if err := ValidateReleaseInput(in); err != nil {
663			return ReleasePlan{}, err
664		}
665		if len(in.Clusters) == 0 {
666			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
667		}
668	
669		selected := []string{}
670		excluded := []ExcludedCluster{}
671		for _, c := range in.Clusters {
672			switch {
673			case c.Disabled:
674				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
675			case matchesAny(c.Tags, in.Exclude):
676				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
677			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
678				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
679			default:
680				selected = append(selected, c.ID)
681			}
682		}
683	
684		sort.Strings(selected)
685		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
686	
687		if len(selected) == 0 {
688			var b strings.Builder
689			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
690			for _, e := range excluded {
691				b.WriteString("\n  ")
692				b.WriteString(reportClusterID(e.ID))
693				b.WriteString("：")
694				b.WriteString(e.Reason)
695			}
696			return ReleasePlan{}, errors.New(b.String())
697		}
698	
699		var batches []Batch
700		if in.SpreadBy == "" {
701			batches = chunkBatches(selected, in.BatchSize)
702		} else {
703			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
704			if err != nil {
705				return ReleasePlan{}, err
706			}
707			batches = spreadBatches(selected, domains, in.BatchSize)
708		}
709	
710		return ReleasePlan{
711			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
712			Batches:  batches,
713			Excluded: excluded,
714		}, nil
715	}
716	
717	// chunkBatches splits the ascending IDs into batches of at most batchSize.
718	// Each batch's Clusters gets its own backing array: a subslice of selected
719	// would leave spare capacity pointing at the next batch's IDs, so a caller
720	// appending to one batch's list would overwrite the following batch.
721	func chunkBatches(selected []string, batchSize int) []Batch {
722		batches := []Batch{}
723		for i := 0; i < len(selected); i += batchSize {
724			end := i + batchSize
725			if end > len(selected) {
726				end = len(selected)
727			}
728			clusters := make([]string, end-i)
729			copy(clusters, selected[i:end])
730			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: clusters})
731		}
732		return batches
733	}
734	
735	// faultDomains maps every selected cluster ID to the exact value of its
736	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
737	// selected is ascending, so the smallest such ID is reported. An empty
738	// string tag value is a valid fault domain, distinct from a missing tag.
739	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
740		tagsByID := make(map[string]map[string]string, len(clusters))
741		for _, c := range clusters {
742			tagsByID[c.ID] = c.Tags
743		}
744		domains := make(map[string]string, len(selected))
745		for _, id := range selected {
746			v, ok := tagsByID[id][spreadBy]
747			if !ok {
748				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
749			}
750			domains[id] = v
751		}
752		return domains, nil
753	}
754	
755	// spreadBatches packs the ascending IDs into batches of at most batchSize
756	// with at most one cluster per fault domain in each batch. Each batch takes
757	// the smallest still-unscheduled IDs whose domains do not conflict with the
758	// batch; conflicting clusters are deferred to later batches, so a batch may
759	// be short only when no non-conflicting cluster remains. Every ID appears in
760	// exactly one batch and IDs stay ascending within a batch.
761	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
762		remaining := append([]string(nil), selected...)
763		batches := []Batch{}
764		for len(remaining) > 0 {
765			// The map never holds more entries than there are remaining clusters,
766			// so size it by them — never by batchSize, which is only an upper
767			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
768			used := make(map[string]struct{}, min(batchSize, len(remaining)))
769			batch := []string{}
770			deferred := []string{}
771			for _, id := range remaining {
772				d := domains[id]
773				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
774					used[d] = struct{}{}
775					batch = append(batch, id)
776				} else {
777					deferred = append(deferred, id)
778				}
779			}
780			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
781			remaining = deferred
782		}
783		return batches
784	}
785	
786	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
787		for _, cond := range conditions {
788			if matchesAll(tags, cond) {
789				return true
790			}
791		}
792		return false
793	}
794	
795	func matchesAll(tags map[string]string, cond LabelCondition) bool {
796		for k, v := range cond {
797			tv, ok := tags[k]
798			if !ok || tv != v {
799				return false
800			}
801		}
802		return true
803	}
